/* 会话状态/安全文本绑定；模拟数据不上传。旧v2演示不兼容，改用独立v3键。 */
window.Eam = (() => {
  const key='eam-demo-v3';let s=EamDomain.initial();
  try {const stored=JSON.parse(sessionStorage.getItem(key)||'null');if(stored?.schema===3)s={...s,...stored};} catch {}
  if(window.EAM_EQUIPMENT_SAMPLES&&!s.equipmentSamplesV1){for(const e of EAM_EQUIPMENT_SAMPLES.equipment)if(!s.equipmentRecords.some(x=>x.id===e.id||x.code===e.code))s.equipmentRecords.push(structuredClone(e));for(const p of EAM_EQUIPMENT_SAMPLES.parts)if(s.equipmentRecords.some(e=>e.id===p.equipmentId)&&!s.parts.some(x=>x.id===p.id))s.parts.push(structuredClone(p));s.equipmentSamplesV1=true;}
  s.drafts ||= {};s.checks ||= [];if(s.check&&!s.checks.some(c=>c.id===s.check.id))s.checks.push(s.check);
  const save=()=>sessionStorage.setItem(key,JSON.stringify(s));
  const role=()=>EAM_DEMO.roles.find(r=>r[0]===s.role);
  const person=()=>EamDomain.people.find(p=>p.id===s.person);
  const message=text=>{const el=document.getElementById('toast');el.textContent=text;el.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.style.display='none',5000);};
  const go=(page,query={},options={})=>{query=options.noContext?query:EamArchiveContext.navigate(page,query,location.search,document.body.dataset.page);save();const params=new URLSearchParams();const view=new URLSearchParams(location.search).get('view');if(view)params.set('view',view);for(const [k,v]of Object.entries(query))params.set(k,v);location.href=page+'.html'+(params.size?'?'+params:'');};
  const run=(type,payload={})=>{try{EamDomain.command(s,{role:s.role,person:s.person},type,payload);save();return true;}catch(e){message(e.message);return false;}};
  const text=(id,value)=>{const el=document.getElementById(id);if(el)el.textContent=value??'—';};
  const value=id=>document.getElementById(id)?.value.trim()||'';
  const checked=id=>!!document.getElementById(id)?.checked;
  const row=(parent,title,detail,page,query={})=>{const wrap=document.createElement('div');wrap.className='row-item';const info=document.createElement('div');const b=document.createElement('b');b.textContent=title;const p=document.createElement('p');p.className='text-secondary small';p.textContent=detail;info.append(b,p);wrap.append(info);if(page){const button=document.createElement('button');button.type='button';button.className='btn btn-sm btn-outline-secondary';button.textContent='查看';button.onclick=()=>go(page,query);wrap.append(button);}parent.append(wrap);};
  const confirm=(title,callback,details='确认后保留操作记录。')=>{const dialog=document.getElementById('confirm-dialog');text('confirm-title',title);text('confirm-message',details);text('confirm-error','');document.getElementById('confirm-reason').value='';document.getElementById('confirm-cancel').onclick=()=>dialog.close();document.getElementById('confirm-submit').onclick=()=>{const reason=value('confirm-reason');if(!reason){text('confirm-error','请填写操作原因');return;}if(callback(reason)!==false)dialog.close();};dialog.showModal();};
  const can=roles=>roles.includes(s.role);
  const attach=()=>{const files=document.getElementById('evidence-files');if(!files)return;files.onchange=()=>{const accepted=[...files.files].filter(f=>f.size<=5*1024*1024);if(accepted.length!==files.files.length)message('单文件最多5MB，超限文件未添加');const refs=accepted.map(f=>({name:f.name,size:f.size,type:f.type||'未知',object:document.body.dataset.page,actorId:s.person,receivedAt:new Date().toISOString()}));s.attachments.push(...refs);save();text('attachment-list',refs.map(f=>f.name+' · '+f.size+'字节').join('；')||'尚无附件');const target=document.getElementById('evidence-reference');if(target)target.value=refs.map(f=>f.name).join('；');};};
  // 片段助手：统一生成 Bootstrap 结构，供后续卡片/字段行组件化复用。
  const field=(labelText,control)=>{const label=document.createElement('label');label.className='field';label.append(document.createTextNode(labelText));if(control)label.append(control);return label;};
  const card=(title,actions,body)=>{const section=document.createElement('section');section.className='card';if(title){const h=document.createElement('h2');h.className='card-title';h.innerHTML=title;section.append(h);}if(actions){const d=document.createElement('div');d.className='actions';d.innerHTML=actions;section.append(d);}if(body){const b=document.createElement('div');b.className='card-body';b.innerHTML=body;section.append(b);}return section;};
  // 单例浮层：确认对话框与轻提示，缺失时按规范结构注入，页面无需重复书写相同 DOM。
  const ensureToast=()=>{if(document.getElementById('toast'))return;const el=document.createElement('div');el.id='toast';el.setAttribute('role','status');el.setAttribute('aria-live','polite');document.body.append(el);};
  const ensureConfirm=()=>{if(document.getElementById('confirm-dialog'))return;const d=document.createElement('dialog');d.id='confirm-dialog';d.setAttribute('aria-labelledby','confirm-title');const title=document.createElement('h2');title.id='confirm-title';const message=document.createElement('p');message.id='confirm-message';const reason=document.createElement('textarea');reason.id='confirm-reason';const err=document.createElement('p');err.id='confirm-error';err.setAttribute('role','alert');const actions=document.createElement('div');actions.className='actions';const cancel=document.createElement('button');cancel.id='confirm-cancel';cancel.type='button';cancel.textContent='取消';const submit=document.createElement('button');submit.id='confirm-submit';submit.type='button';submit.className='btn btn-sm btn-primary';submit.textContent='确认';actions.append(cancel,submit);d.append(title,message,field('操作原因 *',reason),err,actions);document.body.append(d);};
  ensureToast();ensureConfirm();
  return {s,key,save,role,person,message,go,run,text,value,checked,row,attach,confirm,can,field,card};
})();
